                        break;
                case CDF_SIGNED16:
                        if (!cdf_copy_info(&inp[i], &q[o4], e, sizeof(int16_t)))
                                goto unknown;
                        break;
                case CDF_SIGNED32:
                case CDF_BOOL:
                case CDF_UNSIGNED32:
                case CDF_FLOAT:
                        if (!cdf_copy_info(&inp[i], &q[o4], e, sizeof(int32_t)))
                                goto unknown;
                        break;
                case CDF_SIGNED64:
                case CDF_UNSIGNED64:
                case CDF_DOUBLE:
                case CDF_FILETIME:
                        if (!cdf_copy_info(&inp[i], &q[o4], e, sizeof(int64_t)))
